const CACHE='court-nds-offline-v0.0.1-20261119-pages';
const FILES=['index.html','update.html','style.css?v=0.0.1-layout2','app.mjs?v=0.0.1-layout2','layout.mjs?v=0.0.1-layout2','editor.mjs?v=0.0.1-layout2','viewport.mjs?v=0.0.1-layout2','emulator.mjs','storage.mjs','nds-worker.js','audio-worklet.js','core/nds.js','core/nds.wasm','core/LICENSE.txt','core/NOTICE.html','manifest.webmanifest','icon-192.png','icon-512.png'];
const urls=FILES.map(p=>new URL(p,self.registration.scope).href);
self.addEventListener('install',e=>e.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const url of urls){const r=await fetch(new Request(url,{cache:'reload',credentials:'same-origin'}));if(!r.ok||r.redirected||new URL(r.url).origin!==self.location.origin)throw Error('离线资源未能获取');if(url.endsWith('.wasm')){const bytes=await r.clone().arrayBuffer();if(new DataView(bytes).getUint32(0)!==0x0061736d)throw Error('无效的模拟器文件');}await cache.put(url,r);}await self.skipWaiting();})()));
self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const k of await caches.keys())if(k.startsWith('court-nds-offline-')&&k!==CACHE)await caches.delete(k);await self.clients.claim();})()));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;const u=new URL(e.request.url);if(e.request.mode==='navigate'&&u.pathname===new URL('update.html',self.registration.scope).pathname){e.respondWith((async()=>{try{const r=await fetch(e.request);if(r.ok&&!r.redirected)return r;}catch{}return await(await caches.open(CACHE)).match(new URL('update.html',self.registration.scope).href)||fetch(e.request);})());return;}if(e.request.mode==='navigate'&&(u.pathname===new URL(self.registration.scope).pathname||u.pathname===new URL('index.html',self.registration.scope).pathname)){e.respondWith((async()=>await(await caches.open(CACHE)).match(urls[0])||fetch(e.request))());return;}if(urls.includes(e.request.url))e.respondWith((async()=>await(await caches.open(CACHE)).match(e.request)||fetch(e.request))());});
self.addEventListener('message',e=>{if(e.data?.type==='status')e.waitUntil((async()=>{const cache=await caches.open(CACHE);if(e.data.repair){for(const url of urls){if(await cache.match(url))continue;try{const r=await fetch(new Request(url,{cache:'reload',credentials:'same-origin'}));if(r.ok&&!r.redirected&&new URL(r.url).origin===self.location.origin)await cache.put(url,r);}catch{}}}const ready=(await Promise.all(urls.map(u=>cache.match(u)))).every(Boolean);e.ports[0]?.postMessage({ready,version:CACHE});})());});
